<script setup lang="ts">
import { ref,computed } from 'vue'
import type { Instrument,Trade } from '../domain/types'
import type { StockDesk } from '../composables/useStockDesk'
import { number,signed,percent,shares,currencyName,currencySymbol,trendClass } from '../domain/format'
import BaseDialog from './BaseDialog.vue'
import Icon from './Icon.vue'
const props=defineProps<{desk:StockDesk}>(),emit=defineEmits<{trade:[instrument?:Instrument,trade?:Trade];export:[];toast:[message:string]}>()
const currency=ref('all'),tab=ref('positions'),includeClosed=ref(false),deleting=ref<Trade|null>(null),error=ref('')
const data=computed(()=>props.desk.data.value),positions=computed(()=>props.desk.portfolio.value.positions.filter(p=>(includeClosed.value||p.quantity>0)&&(currency.value==='all'||p.instrument.currency===currency.value)))
const trades=computed(()=>data.value.trades.filter(t=>currency.value==='all'||data.value.instruments[t.symbol]?.currency===currency.value).map((trade,i)=>({trade,i})).sort((a,b)=>b.trade.date.localeCompare(a.trade.date)||b.i-a.i).map(r=>r.trade))
function removeTrade(){try{props.desk.deleteTrade(deleting.value!.id);deleting.value=null;emit('toast','交易已删除，持仓与成本已重新计算')}catch(e){error.value=e instanceof Error?e.message:'删除失败'}}
</script>
<template><section class="portfolio-view"><div class="page-heading"><div><div class="eyebrow">MY PORTFOLIO</div><h1>我的持仓</h1><p>交易记录驱动的持股账本，盈亏清楚，数据只留本地。</p></div><div class="toolbar-actions"><button class="button subtle" @click="emit('export')"><Icon name="download" :size="16"/>导出持仓</button><button class="button primary" data-testid="add-trade" @click="emit('trade')"><Icon name="plus" :size="17"/>记录交易</button></div></div>
 <div v-if="desk.portfolio.value.summaries.length" class="portfolio-summaries"><article v-for="summary in desk.portfolio.value.summaries" :key="summary.currency" class="summary-card surface"><div class="summary-title"><span>{{currencyName(summary.currency)}}</span><span class="currency-label mono">{{summary.currency}}</span></div><span class="metric-label">{{summary.missingQuotes?'已知市值小计':'持仓市值'}}</span><strong class="summary-value mono">{{currencySymbol(summary.currency)}}{{number(summary.marketValue)}}</strong><div class="summary-metrics"><div><span>浮动盈亏</span><strong class="mono" :class="trendClass(summary.unrealizedPnl)">{{signed(summary.unrealizedPnl)}}</strong></div><div><span>行情日盈亏</span><strong class="mono" :class="trendClass(summary.dayPnl)">{{signed(summary.dayPnl)}}</strong></div><div><span>已实现盈亏</span><strong class="mono" :class="trendClass(summary.realizedPnl)">{{signed(summary.realizedPnl)}}</strong></div><div><span>持仓成本</span><strong class="mono">{{number(summary.cost)}}</strong></div></div><p v-if="summary.missingQuotes||summary.missingDayQuotes" class="summary-warning">{{summary.missingQuotes}} 只持仓缺少行情 · {{summary.missingDayQuotes}} 只缺少日盈亏数据；显示已知小计。</p><p v-else class="summary-note">{{summary.positions}} 只持仓 · 行情日盈亏含当日买卖和费用</p></article></div>
 <div class="portfolio-table-panel surface"><div class="portfolio-toolbar"><div class="segmented"><button :class="{active:tab==='positions'}" @click="tab='positions'">持股明细 <span>{{desk.portfolio.value.positions.filter(p=>p.quantity>0).length}}</span></button><button :class="{active:tab==='trades'}" @click="tab='trades'">交易记录 <span>{{data.trades.length}}</span></button></div><div class="portfolio-filters"><label v-if="tab==='positions'"><input v-model="includeClosed" type="checkbox"/>已清仓</label><select v-model="currency" aria-label="持仓币种"><option value="all">全部币种</option><option value="CNY">人民币 CNY</option><option value="HKD">港币 HKD</option><option value="USD">美元 USD</option></select></div></div>
 <div v-if="!data.trades.length" class="empty-state large"><div class="empty-icon"><Icon name="wallet" :size="38"/></div><h3>暂无持仓</h3><p>录入已有持股，或记录第一笔买入交易。<br/>我们会自动计算成本、市值与盈亏。</p><button class="button primary" @click="emit('trade')"><Icon name="plus" :size="17"/>记录第一笔交易</button><span class="empty-footnote"><Icon name="shield" :size="14"/>本地记账，不执行真实交易</span></div>
 <div v-else class="table-scroll"><table v-if="tab==='positions'" class="data-table portfolio-table"><thead><tr><th>股票</th><th>持股数量</th><th>平均成本</th><th>现价 / 市值</th><th>浮动盈亏</th><th>行情日盈亏</th><th>已实现</th><th/></tr></thead><tbody><tr v-for="p in positions" :key="p.instrument.symbol"><td><strong>{{p.instrument.name}}</strong><span class="table-sub mono">{{p.instrument.code}} · {{p.instrument.currency}}</span></td><td class="mono">{{shares(p.quantity)}}</td><td class="mono">{{number(p.averageCost,4)}}</td><td><strong class="mono" :class="trendClass(p.quote?.change)">{{number(p.quote?.price)}}</strong><span class="table-sub mono">{{number(p.marketValue)}} <span v-if="p.quote&&desk.quoteState(p.instrument.symbol)!=='fresh'">快照</span></span></td><td :class="trendClass(p.unrealizedPnl)"><strong class="mono">{{signed(p.unrealizedPnl)}}</strong><span class="table-sub mono">{{percent(p.unrealizedPercent)}}</span></td><td class="mono" :class="trendClass(p.dayPnl)">{{signed(p.dayPnl)}}</td><td class="mono" :class="trendClass(p.realizedPnl)">{{signed(p.realizedPnl)}}</td><td><button class="icon-button" :aria-label="`记录${p.instrument.name}交易`" @click="emit('trade',p.instrument)"><Icon name="plus" :size="17"/></button></td></tr></tbody></table>
 <table v-else class="data-table"><thead><tr><th>交易日期 / 股票</th><th>类型</th><th>数量</th><th>成交价</th><th>费用</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="t in trades" :key="t.id"><td><strong>{{data.instruments[t.symbol]?.name}}</strong><span class="table-sub mono">{{t.date}} · {{data.instruments[t.symbol]?.currency}}</span></td><td><span class="trade-type" :class="t.type">{{t.type==='buy'?'买入':t.type==='sell'?'卖出':'期初'}}</span></td><td class="mono">{{shares(t.quantity)}}</td><td class="mono">{{number(t.price,4)}}</td><td class="mono">{{number(t.fees)}}</td><td class="trade-note" :title="t.note">{{t.note||'—'}}</td><td class="ledger-actions"><button class="icon-button" aria-label="编辑交易" @click="emit('trade',data.instruments[t.symbol],t)"><Icon name="edit" :size="15"/></button><button class="icon-button" aria-label="删除交易" @click="deleting=t;error='' "><Icon name="trash" :size="15"/></button></td></tr></tbody></table>
 <p v-if="tab==='positions'&&!positions.length" class="table-empty">当前筛选下没有持股；可开启“已清仓”查看已实现盈亏。</p></div>
 </div><div class="info-strip"><Icon name="info" :size="16"/><span>币种独立汇总，不擅自换算汇率。采用加权平均成本，买入费用计入成本、卖出费用扣除收入。日盈亏以行情交易日为准。</span></div>
 <BaseDialog v-if="deleting" title="删除这笔交易？" @close="deleting=null"><div class="dialog-form"><p>将删除 {{data.instruments[deleting.symbol]?.name}} {{deleting.date}} 的记录，并重新计算全部持股成本。</p><p class="inline-notice">如果删除后导致历史卖出数量超过持股，系统会拒绝删除。该操作不可撤销，建议先导出备份。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="dialog-actions"><button class="button subtle" @click="deleting=null">取消</button><button class="button danger" @click="removeTrade">确认删除</button></div></div></BaseDialog>
</section></template>
